const root="/home/axel/LeanAlgebraicGeometry-Horizon";
const qs=[
 ["i1982","sed -n '1,220p' .archon-horizon/inbox/local/items/I-1982.yaml",root],
 ["i1980","sed -n '1,220p' .archon-horizon/inbox/local/items/I-1980.yaml",root],
 ["i1979","sed -n '1,220p' .archon-horizon/inbox/local/items/I-1979.yaml",root],
 ["review-baseline","nl -ba MainProjects/Algebraic-Jacobian-Challenge-Rebuild/informal/review-phase0-baseline.md | sed -n '85,125p'",root],
 ["p8","nl -ba .archon-horizon/roadmap/items/AJCR.review-plan.p8-jacobian.yaml | sed -n '1,100p'",root]
];
const rs=await Promise.all(qs.map(async([n,c,w])=>({n,r:await tools.exec_command({cmd:c,workdir:w,yield_time_ms:10000,max_output_tokens:20000})})));
for(const {n,r} of rs) text(`===== ${n} =====\n${r.output}`);

const base="/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects";
const qs=[
 ["rebuild-lake","nl -ba lakefile.toml 2>/dev/null || nl -ba lakefile.lean; nl -ba lean-toolchain",`${base}/Algebraic-Jacobian-Challenge-Rebuild`],
 ["sibling-lake","nl -ba lakefile.toml 2>/dev/null || nl -ba lakefile.lean; nl -ba lean-toolchain",`${base}/Algebraic-Jacobian-Challenge`],
 ["rebuild-manifest","sed -n '1,180p' lake-manifest.json",`${base}/Algebraic-Jacobian-Challenge-Rebuild`],
 ["sibling-manifest","sed -n '1,180p' lake-manifest.json",`${base}/Algebraic-Jacobian-Challenge`],
 ["same-modules","comm -12 <(rg --files AlgebraicJacobian | sort) <(cd ../Algebraic-Jacobian-Challenge && rg --files AlgebraicJacobian | sort) | sed -n '1,220p'",`${base}/Algebraic-Jacobian-Challenge-Rebuild`]
];
const rs=await Promise.all(qs.map(async([n,c,w])=>({n,r:await tools.exec_command({cmd:c,workdir:w,yield_time_ms:10000,max_output_tokens:30000})})));
for(const {n,r} of rs) text(`===== ${n} =====\n${r.output}`);

const wd="/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge";
const qs=[
 ["identitycomp","nl -ba AlgebraicJacobian/Picard/IdentityComponent.lean | sed -n '700,790p'",wd],
 ["identitycomp-def","rg -n 'identityComponentSubgroupFunctor|identityComponentRepresentableBy|RepresentableBy' AlgebraicJacobian/Picard/IdentityComponent.lean | sed -n '1,180p'",wd],
 ["hasgalois-lft","rg -n 'seamClauseOne_of_hasGaloisQuotient_lftFree|instance.*HasGaloisQuotient|hasGaloisQuotient_of' AlgebraicJacobian/Picard/*.lean AlgebraicJacobian/Picard/GaloisDescent/*.lean",wd],
 ["hasgalois-context","nl -ba AlgebraicJacobian/Picard/PicEtPointedReduction.lean | sed -n '245,325p'",wd]
];
const rs=await Promise.all(qs.map(async([n,c,w])=>({n,r:await tools.exec_command({cmd:c,workdir:w,yield_time_ms:10000,max_output_tokens:25000})})));
for(const {n,r} of rs) text(`===== ${n} =====\n${r.output}`);
